            '  issues: write'
        ].join('\n');
        var dups = lint.findDuplicateKeys(yml);
        assert.equal(dups.length, 1);
        assert.equal(dups[0].key, 'issues');
        assert.equal(dups[0].line, 4);
    });

    test('the exact #671 shape — two duplicated permission keys, both reported', function () {
        var yml = [
