            'the dedup gate keys the assignee check to the assigned action');
        assert.ok(dedupIf.indexOf("github.event_name == 'workflow_dispatch'") !== -1,
            'the dedup gate preserves the dispatch path (probe outputs proceed=true there)');
    });

